package org.marketreview.nativeapp;
import android.content.Context;
import android.view.*;
import android.widget.*;
import org.json.*;
public final class AccountReferenceScreen extends LinearLayout {
 public interface Reader{JSONObject read()throws Exception;}
 private final Reader reader;private final TextView summary;private final LinearLayout content;private JSONObject output=new JSONObject();private boolean dark;
 public AccountReferenceScreen(Context c,Reader r){super(c);reader=r;setOrientation(VERTICAL);setTag("accountReferenceScreen");Button reload=new Button(c);reload.setText("重读冻结本机输入");reload.setTag("accountReferenceReload");addView(reload);ScrollView scroll=new ScrollView(c);content=new LinearLayout(c);content.setOrientation(VERTICAL);scroll.addView(content);addView(scroll,new LayoutParams(-1,0,1));summary=text("");summary.setTag("accountReferenceSummary");content.addView(summary);reload.setOnClickListener(v->reload());reload();}
 private TextView text(String s){TextView t=new TextView(getContext());t.setText(s);t.setTextSize(13);t.setPadding(8,6,8,6);t.setTextColor(dark?0xffdce5f0:0xff243449);return t;}
 private static String show(Object o){return o==null||o==JSONObject.NULL?"未知":o.toString();}
 public JSONObject frozenOutput()throws Exception{return new JSONObject(output.toString());}
 public void reload(){output=new JSONObject();content.removeAllViews();content.addView(summary);try{if(reader==null)throw new Exception("宿主未接只读冻结输入");JSONObject next=reader.read();if(!next.optString("schema").equals("native-account-reference/v1"))throw new Exception("参考盈亏结果格式无效");output=new JSONObject(next.toString());JSONObject coverage=output.getJSONObject("quoteCoverage");summary.setText("账户 "+show(output.opt("accountId"))+" · 参考日期 "+show(output.opt("date"))+" · 冻结 "+show(output.opt("asOf"))+"\n当日参考 "+show(output.opt("todayReferencePnl"))+" 元（旧未清仓范围） · 累计简单成本比例 "+show(output.opt("totalPnlRate"))+"% · 历次买入金额 "+show(output.opt("lifetimeBuyCost"))+" 元\n报价覆盖 "+show(coverage.opt("priced"))+"/"+show(coverage.opt("total"))+" · 匹配 "+show(coverage.opt("live"))+" · 旧/未核时点 "+show(coverage.opt("stale"))+" · 缺失 "+show(coverage.opt("missing"))+"\n"+output.optString("boundary"));JSONArray rows=output.getJSONArray("contributions");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);TextView item=text(row.optString("name")+" · "+(row.optBoolean("includedInLegacyDaily")?"未清仓":"已清仓（不纳入旧当日汇总）")+"\n当日参考 "+show(row.opt("todayReferencePnl"))+" · 累计贡献 "+show(row.opt("totalPnl"))+" 元 · 成本比例贡献 "+show(row.opt("totalPnlRateContribution"))+" 百分点\n期初 "+show(row.opt("openingQuantity"))+" → 期末 "+show(row.opt("endQuantity"))+" 股 · 当日现金流 "+show(row.opt("dayCashFlow"))+" 元\n报价 "+row.optString("quoteDate")+" "+row.optString("quoteTime")+" · "+row.optString("quoteSource")+" / "+row.optString("quoteStatus")+"\n点击查看计算依据");item.setTag("accountReferenceRow_"+i);item.setContentDescription(row.optString("instrumentId"));LinearLayout detail=basis(row,i);detail.setVisibility(GONE);item.setOnClickListener(v->detail.setVisibility(detail.getVisibility()==GONE?VISIBLE:GONE));content.addView(item);content.addView(detail);}content.addView(text(new JSONObject().put("issues",output.opt("issues")).put("excludedFutureTrades",output.opt("excludedFutureTrades")).toString(2)));}catch(Exception e){output=new JSONObject();content.removeAllViews();content.addView(summary);summary.setText(e.getMessage());}}
 private LinearLayout basis(JSONObject row,int index)throws Exception{String full=row.toString(2);final int[] offset={0};LinearLayout panel=new LinearLayout(getContext());panel.setOrientation(VERTICAL);panel.setTag("accountReferenceDetail_"+index);TextView body=text(full.substring(0,Math.min(full.length(),24000)));body.setTag("accountReferenceBasis_"+index);body.setTextIsSelectable(true);panel.addView(body);LinearLayout nav=new LinearLayout(getContext());panel.addView(nav);for(int direction:new int[]{-1,1}){Button button=new Button(getContext());button.setText(direction<0?"上一段":"下一段");button.setTag(direction<0?"accountReferencePrevious_"+index:"accountReferenceNext_"+index);nav.addView(button,new LayoutParams(0,-2,1));button.setOnClickListener(v->{offset[0]=Math.max(0,Math.min(Math.max(0,(full.length()-1)/24000*24000),offset[0]+direction*24000));body.setText(full.substring(offset[0],Math.min(full.length(),offset[0]+24000)));});}return panel;}
 private void colors(View v){if(v instanceof TextView)((TextView)v).setTextColor(dark?0xffdce5f0:0xff243449);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)colors(g.getChildAt(i));}}
 public void setDarkTheme(boolean value){dark=value;setBackgroundColor(dark?0xff111a26:0xffffffff);colors(this);}
}

